        { "text", text = "Starshards: |cOXP_FRIENDLY_Brother Joshua|r" },
        { "text", text = "At 10 in Stormwind, |cOXP_FRIENDLY_Brother Joshua|r at the altar of the Cathedral of Light hands you Returning Home, a letter for |cOXP_FRIENDLY_Priestess Alathea|r in Darnassus. |cOXP_FRIENDLY_Nara Meideros|r in the Park has the same letter." },
        { "xp", level = 10, text = "Reach level 10" },
        { "goto", x = 49.5, y = 45.21, zone = "1453" },
        { "text", text = "Use Brother Joshua (|cOXP_FRIENDLY_Brother Joshua|r: take Returning Home)" },
      },
      { only = "Priest", when = { { "zone", name = "Ironforge" }, { "onquest", neg = true, quests = { 5627, 5628, 5629, 5630, 5631, 5632, 5633 } } },
        { "text", text = "Starshards: |cOXP_FRIENDLY_Braenna Flintcrag|r" },
        { "text", text = "At 10 in Ironforge, |cOXP_FRIENDLY_Braenna Flintcrag|r in the |cOXP_PICK_Hall of Mysteries|r (|cOXP_PICK_Mystic Ward|r) hands you Returning Home, a letter for |cOXP_FRIENDLY_Priestess Alathea|r in Darnassus." },
        { "xp", level = 10, text = "Reach level 10" },
        { "goto", x = 24.42, y = 9.17, zone = "1455" },
        { "text", text = "Use Braenna Flintcrag (|cOXP_FRIENDLY_Braenna Flintcrag|r: take Returning Home)" },
      },
      { only = "Priest", when = { { "onquest", neg = true, quests = { 5627, 5628, 5629, 5630, 5631, 5632, 5633 } } },
        { "text", text = "Starshards: |cOXP_FRIENDLY_Priestess Alathea|r" },
        { "text", text = "At 10, go to |cOXP_FRIENDLY_Priestess Alathea|r on the upper balcony of the Temple of the Moon, at the south end of Darnassus: take the ramp up from the temple floor; she stands beside |cOXP_FRIENDLY_Tyrande Whisperwind|r. Stars of Elune is given and taken back at once and teaches Starshards. No letter needed. Forever made Starshards hit much harder, on a 30-second cooldown." },
        { "xp", level = 10, text = "Reach level 10" },
        { "goto", x = 39.52, y = 81.2, zone = "1457" },
        { "accept", quest = 5627, text = "Accept Stars of Elune" },
        { "target", name = "Priestess Alathea" },
        { "goto", x = 39.52, y = 81.2, zone = "1457" },
        { "turnin", quest = 5627, text = "Turn in Stars of Elune (|cOXP_FRIENDLY_Priestess Alathea|r: Starshards)" },
        { "target", name = "Priestess Alathea" },
      },
      { only = "Priest", when = { { "onquest", quests = { 5629 } } },
        { "text", text = "Starshards: |cOXP_FRIENDLY_Laurna Morninglight|r's letter" },
        { "text", text = "Take the road west from Dolanaar into Darnassus and go up to the upper balcony of the Temple of the Moon, beside |cOXP_FRIENDLY_Tyrande Whisperwind|r: |cOXP_FRIENDLY_Priestess Alathea|r takes Returning Home and teaches Starshards." },
        { "goto", x = 39.52, y = 81.2, zone = "1457" },
        { "turnin", quest = 5629, text = "Turn in Returning Home (|cOXP_FRIENDLY_Priestess Alathea|r: Starshards)" },
        { "target", name = "Priestess Alathea" },
      },
      { only = "Priest", when = { { "onquest", quests = { 5628 } } },
        { "text", text = "Starshards: Josetta's letter" },
        { "text", text = "Returning Home goes to |cOXP_FRIENDLY_Priestess Alathea|r, on the upper balcony of the Temple of the Moon in Darnassus, beside |cOXP_FRIENDLY_Tyrande Whisperwind|r: take the boat from Stormwind Harbor (or Menethil Harbor) to Auberdine, the boat on to Rut'theran Village, then the portal up into Darnassus." },
        { "goto", x = 39.52, y = 81.2, zone = "1457" },
        { "turnin", quest = 5628, text = "Turn in Returning Home (|cOXP_FRIENDLY_Priestess Alathea|r: Starshards)" },
