      { only = "Priest", when = { { "zone", name = "Stormwind City" }, { "onquest", neg = true, quests = { 94818, 94819, 94820 } } },
        { "text", text = "Contingency Plan: |cOXP_FRIENDLY_High Priestess Laurena|r" },
        { "text", text = "At 20 in Stormwind, |cOXP_FRIENDLY_High Priestess Laurena|r at the altar of the Cathedral of Light hands you a Contingency Plan letter for |cOXP_FRIENDLY_High Priestess Mims|r in Ironforge (the Deeprun Tram from the |cOXP_PICK_Dwarven District|r)." },
        { "xp", level = 20, text = "Reach level 20" },
        { "goto", x = 49.53, y = 44.6, zone = "1453" },
        { "text", text = "Use High Priestess Laurena (|cOXP_FRIENDLY_High Priestess Laurena|r: take her Contingency Plan letter)" },
      },
      { only = "Priest", when = { { "onquest", neg = true, quests = { 94818, 94819, 94820 } } },
        { "text", text = "Contingency Plan: |cOXP_FRIENDLY_High Priestess Mims|r" },
        { "text", text = "At 20, |cOXP_FRIENDLY_High Priestess Mims|r in the |cOXP_PICK_Hall of Mysteries|r teaches Contingency Plan with a quest she gives and takes back at once. Contingency Plan wards a friend for 30 seconds: if they drop below 35% health, they get a shield and a heal over time at once (it stacks with Renew and Power Word: Shield). 5-minute cooldown." },
        { "xp", level = 20, text = "Reach level 20" },
        { "goto", x = 24.59, y = 10, zone = "1455" },
        { "accept", quest = 94818, text = "Accept Contingency Plan" },
        { "target", name = "High Priestess Mims" },
        { "goto", x = 24.59, y = 10, zone = "1455" },
        { "turnin", quest = 94818, text = "Turn in Contingency Plan (|cOXP_FRIENDLY_High Priestess Mims|r: Contingency Plan)" },
