        { "goto", x = 41.15, y = 66.23, zone = "1429" },
        { "turnin", quest = 94864, text = "Turn in Taming the Beast (|cOXP_FRIENDLY_Josephine Carson|r: Tame Beast)" },
        { "target", name = "Josephine Carson" },
        { "goto", x = 41.15, y = 66.23, zone = "1429" },
        { "accept", quest = 94793, text = "Accept Training the Beast" },
        { "target", name = "Josephine Carson" },
        { "goto", x = 41.79, y = 66.37, zone = "1429" },
        { "turnin", quest = 94793, text = "Turn in Training the Beast (|cOXP_FRIENDLY_Isaac Chan|r, beside her: Beast Training)" },
        { "target", name = "Isaac Chan" },
      },
      {
        { "text", text = "|cOXP_FRIENDLY_Golnir Bouldertoe|r" },
        { "text", text = "The gryphons land in the |cOXP_PICK_Great Forge|r: |cOXP_FRIENDLY_Golnir Bouldertoe|r works at its north end, and |cOXP_FRIENDLY_Gryth Thurden|r keeps the gryphons where you landed." },
        { "goto", x = 51.52, y = 26.31, zone = "1455" },
        { "turnin", quest = 6391, text = "Turn in Ride to Ironforge (|cOXP_FRIENDLY_Golnir Bouldertoe|r, in the |cOXP_PICK_Great Forge|r)" },
        { "target", name = "Golnir Bouldertoe" },
        { "goto", x = 51.52, y = 26.31, zone = "1455" },
        { "accept", quest = 6388, text = "Accept Gryth Thurden" },
        { "target", name = "Golnir Bouldertoe" },
