      { only = "NightElf Hunter", when = { { "onquest", neg = true, quests = { 94792, 94863, 94864, 94793 } }, { "turnedin", neg = true, quest = 94792 } },
        { "text", text = "|cOXP_FRIENDLY_Jocaste|r in Darnassus" },
        { "text", text = "Take the road west from Dolanaar to Darnassus. |cOXP_FRIENDLY_Jocaste|r stands inside the Cenarion Enclave with the hunter trainers; Silvaria, the pet trainer, is up the ramp next to her." },
        { "goto", x = 40.38, y = 8.55, zone = "1457" },
