      { only = "Priest", when = { { "zone", name = "Teldrassil" }, { "onquest", neg = true, quests = { 5627, 5628, 5629, 5630, 5631, 5632, 5633 } } },
        { "text", text = "Class quest: {spell:10797} and {spell:2651}" },
        { "text", text = "Starshards: |cOXP_FRIENDLY_Laurna Morninglight|r" },
        { "text", text = "At 10, |cOXP_FRIENDLY_Laurna Morninglight|r, the priest trainer in the building at the north edge of Dolanaar, hands you Returning Home, a letter for |cOXP_FRIENDLY_Priestess Alathea|r in Darnassus. Dolanaar is on the road west to Darnassus." },
        { "xp", level = 10, text = "Reach level 10" },
        { "goto", x = 55.56, y = 56.75, zone = "1438" },
        { "text", text = "Use Laurna Morninglight (|cOXP_FRIENDLY_Laurna Morninglight|r: take Returning Home)" },
      },
      { only = "Priest", when = { { "zone", name = "Elwynn Forest" }, { "onquest", neg = true, quests = { 5627, 5628, 5629, 5630, 5631, 5632, 5633 } } },
        { "text", text = "Starshards: |cOXP_FRIENDLY_Priestess Josetta|r" },
        { "text", text = "At 10 in Elwynn Forest, |cOXP_FRIENDLY_Priestess Josetta|r, upstairs in the Lion's Pride Inn in Goldshire, hands you Returning Home, a letter for |cOXP_FRIENDLY_Priestess Alathea|r in Darnassus." },
        { "xp", level = 10, text = "Reach level 10" },
        { "goto", x = 43.28, y = 65.72, zone = "1429" },
        { "text", text = "Use Priestess Josetta (|cOXP_FRIENDLY_Priestess Josetta|r: take Returning Home)" },
