      { only = "Shaman", when = { { "turnedin", neg = true, quest = 98581 } },
        { "text", text = "Class quest: {quest:94373} (Alliance)" },
        { "text", text = "Archaic Rune" },
        { "text", text = "Teo's Call of Earth needs the Archaic Rune handed in first: |cOXP_FRIENDLY_Sten Stoutarm|r, where you entered Coldridge Valley, gives it to Dwarf shamans after his Dwarven Outfitters. Bring it up the road to |cOXP_FRIENDLY_Teo Hammerstorm|r inside Anvilmar." },
        { "goto", x = 29.93, y = 71.2, zone = "1426" },
        { "accept", quest = 98581, text = "Accept Archaic Rune" },
        { "target", name = "Sten Stoutarm" },
        { "goto", x = 28.79, y = 66.18, zone = "1426" },
        { "turnin", quest = 98581, text = "Turn in Archaic Rune" },
        { "target", name = "Teo Hammerstorm" },
      },
      { only = "Shaman",
        { "text", text = "|cOXP_FRIENDLY_Teo Hammerstorm|r" },
        { "text", text = "|cOXP_FRIENDLY_Teo Hammerstorm|r trains shamans inside Anvilmar, the hall at the south end of Coldridge Valley. The quest opens at level 4. Never took it and now 10 or more? |cOXP_FRIENDLY_Eldrun Stormbreaker|r in Ironforge or |cOXP_FRIENDLY_Ingrid Dunwald|r in Kharanos gives you Call of Earth, a pointer back to Teo: take it for the experience on the way." },
        { "xp", level = 4, text = "Reach level 4" },
        { "goto", x = 28.79, y = 66.18, zone = "1426" },
        { "accept", quest = 94373, text = "Accept Call of Earth" },
        { "target", name = "Teo Hammerstorm" },
      },
      { only = "Shaman",
        { "text", text = "Iceclaw Bear Pendants" },
        { "text", text = "The Frostmane Troll Whelps (level 3-4) hold the snowy slopes west and south-west of Anvilmar, and the Frostmane Novices (level 3-4, they throw Frostbolts from range) camp south of it. Both carry the pendants; they respawn in about three minutes." },
        { "goto", x = 27.7, y = 78.82, zone = "1426" },
        { "complete", obj = 1, quest = 94373, text = "Iceclaw Bear Pendant: 2" },
        { "mob", name = "Frostmane Troll Whelp" },
        { "mob", name = "Frostmane Novice" },
      },
      { only = "Shaman",
        { "text", text = "|cOXP_FRIENDLY_Teo Hammerstorm|r" },
        { "text", text = "Back to Teo inside Anvilmar. He hands you the |cOXP_LOOT_Earth Sapta|r: do not drink it yet." },
        { "goto", x = 28.79, y = 66.18, zone = "1426" },
        { "turnin", quest = 94373, text = "Turn in Call of Earth" },
        { "target", name = "Teo Hammerstorm" },
        { "goto", x = 28.79, y = 66.18, zone = "1426" },
        { "accept", quest = 94374, text = "Accept Call of Earth" },
        { "target", name = "Teo Hammerstorm" },
      },
      { only = "Shaman", when = { { "onquest", quests = { 94374 } }, { "has", item = 6635, n = 1, neg = true } },
        { "text", text = "Lost the Earth Sapta?" },
        { "text", text = "Only if the Earth Sapta is gone from your bags (drunk away from the stone, or sold): Teo gives you another." },
        { "goto", x = 28.79, y = 66.18, zone = "1426" },
        { "turnin", quest = 94472, text = "Turn in Earth Sapta (|cOXP_FRIENDLY_Teo Hammerstorm|r: a new Earth Sapta)" },
        { "target", name = "Teo Hammerstorm" },
      },
      { only = "Shaman",
        { "text", text = "The Spirit Stone" },
        { "text", text = "The Spirit Stone stands on a snowy ridge north-west of Anvilmar. The trail is easy to miss: it climbs the hill from the valley floor; at the small camp near the top turn left and the stone comes into view. Stand beside it, drink the |cOXP_LOOT_Earth Sapta|r and speak to the |cOXP_FRIENDLY_Minor Manifestation of Earth|r before it fades." },
        { "goto", x = 24.8, y = 61.8, zone = "1426" },
        { "item", item = 6635, text = "Use Earth Sapta (|cOXP_LOOT_Earth Sapta|r, beside the Spirit Stone)" },
        { "goto", x = 24.8, y = 61.8, zone = "1426" },
        { "turnin", quest = 94374, text = "Turn in Call of Earth" },
        { "target", name = "Minor Manifestation of Earth" },
        { "goto", x = 24.8, y = 61.8, zone = "1426" },
        { "accept", quest = 94375, text = "Accept Call of Earth (it hands you the |cOXP_LOOT_Rough Quartz|r: keep it)" },
        { "target", name = "Minor Manifestation of Earth" },
      },
      { only = "Shaman",
        { "text", text = "|cOXP_FRIENDLY_Teo Hammerstorm|r" },
        { "text", text = "Bring the |cOXP_LOOT_Rough Quartz|r back to Teo inside Anvilmar. Keep the |cOXP_LOOT_Earth Totem|r in your bags for good: every earth totem needs it." },
        { "goto", x = 28.79, y = 66.18, zone = "1426" },
        { "turnin", quest = 94375, text = "Turn in Call of Earth (|cOXP_FRIENDLY_Teo Hammerstorm|r: Stoneskin Totem and your |cOXP_LOOT_Earth Totem|r)" },
        { "target", name = "Teo Hammerstorm" },
        { "goto", only = "Shaman", x = 28.79, y = 66.18, zone = "1426" },
        { "train", only = "Shaman", text = "Train at |cOXP_FRIENDLY_Teo Hammerstorm|r" },
        { "target", name = "Teo Hammerstorm", only = "Shaman" },
      },
