        { "text", text = "Use Priestess Josetta (|cOXP_FRIENDLY_Priestess Josetta|r: take her Confounding Flash letter)" },
      },
      { only = "Priest", when = { { "zone", name = "Stormwind City" }, { "onquest", neg = true, quests = { 94817, 94821, 94822, 94823, 94824, 94825, 94826 } } },
        { "text", text = "Confounding Flash: |cOXP_FRIENDLY_High Priestess Laurena|r" },
        { "text", text = "At 10 in Stormwind, |cOXP_FRIENDLY_High Priestess Laurena|r at the altar of the Cathedral of Light hands you a Confounding Flash letter for |cOXP_FRIENDLY_High Priestess Mims|r in Ironforge (the Deeprun Tram from the |cOXP_PICK_Dwarven District|r)." },
        { "xp", level = 10, text = "Reach level 10" },
        { "goto", x = 49.53, y = 44.6, zone = "1453" },
        { "text", text = "Use High Priestess Laurena (|cOXP_FRIENDLY_High Priestess Laurena|r: take her Confounding Flash letter)" },
      },
      { only = "Priest", when = { { "onquest", neg = true, quests = { 94817, 94821, 94822, 94823, 94824, 94825, 94826 } } },
        { "text", text = "Confounding Flash: |cOXP_FRIENDLY_High Priestess Mims|r" },
        { "text", text = "At 10, go to |cOXP_FRIENDLY_High Priestess Mims|r in the |cOXP_PICK_Hall of Mysteries|r, Ironforge's |cOXP_PICK_Mystic Ward|r (north-west of the city), right beside |cOXP_FRIENDLY_High Priest Rohan|r: she gives Confounding Flash and takes it back at once. No letter needed. Confounding Flash confuses up to five enemies around you for 3 seconds (any damage wakes them) on a 2-minute cooldown: time to step back and heal, or to run." },
        { "xp", level = 10, text = "Reach level 10" },
        { "goto", x = 24.59, y = 10, zone = "1455" },
        { "accept", quest = 94817, text = "Accept Confounding Flash" },
