      { only = "Warrior", when = { { "turnedin", neg = true, quest = 1679 }, { "turnedin", neg = true, quest = 1684 } },
        { "text", text = "|cOXP_FRIENDLY_Marshal Haggard|r" },
        { "text", text = "|cOXP_FRIENDLY_Marshal Haggard|r's manor stands at the south-east edge of the Eastvale Logging Camp in eastern Elwynn, at the end of a short road that does not join the main one." },
        { "goto", x = 84.61, y = 69.38, zone = "1429" },
        { "turnin", quest = 1666, text = "Turn in Marshal Haggard" },
        { "target", name = "Marshal Haggard" },
        { "goto", x = 84.61, y = 69.38, zone = "1429" },
        { "accept", quest = 1667, text = "Accept Dead-tooth Jack" },
        { "target", name = "Marshal Haggard" },
      },
      { only = "Warrior", when = { { "turnedin", neg = true, quest = 1679 }, { "turnedin", neg = true, quest = 1684 } },
        { "text", text = "Dead-tooth Jack" },
        { "text", text = "|cOXP_ENEMY_Dead-Tooth Jack|r (level 11) camps in the far south-east of Elwynn. A guard stands beside him and Defias and wolves are spread around the camp (now and then a rarer guard too): clear them one at a time, then kill Jack. He always drops |cOXP_LOOT_Dead-tooth's Key|r; open |cOXP_PICK_Dead-tooth's Strongbox|r in the crates by him for |cOXP_LOOT_Marshal Haggard's Badge|r. Jack returns 3 minutes after dying, the box 1 minute after opening." },
        { "goto", x = 89.36, y = 79.03, zone = "1429" },
        { "item", item = 6783, text = "Dead-tooth's Key: 1 (from |cOXP_ENEMY_Dead-Tooth Jack|r)" },
        { "goto", x = 89.33, y = 78.88, zone = "1429" },
        { "complete", obj = 1, quest = 1667, text = "Marshal Haggard's Badge: 1 (|cOXP_LOOT_Marshal Haggard's Badge|r, from |cOXP_PICK_Dead-tooth's Strongbox|r)" },
      },
      { only = "Warrior", when = { { "turnedin", neg = true, quest = 1679 }, { "turnedin", neg = true, quest = 1684 } },
        { "text", text = "Back to |cOXP_FRIENDLY_Marshal Haggard|r" },
        { "goto", x = 84.61, y = 69.38, zone = "1429" },
        { "turnin", quest = 1667, text = "Turn in Dead-tooth Jack" },
        { "target", name = "Marshal Haggard" },
      },
      { only = "Warlock",
        { "text", text = "The Binding" },
        { "text", text = "Back to |cOXP_FRIENDLY_Gakin the Darkbinder|r. He hands you the |cOXP_LOOT_Bloodstone Choker|r. The circle is hard to find: take the stairs behind |cOXP_FRIENDLY_Gakin the Darkbinder|r down; part way along the lowest corridor a side stair on the left leads into a room with a glowing purple circle in the middle. Stand on it and use the choker. The voidwalker (level 10, not elite) gets dangerous below 30% health: Curse of Agony, Corruption and Immolate with your imp on it, Fear when it gets close. If it beats you, use the choker again. Keep the choker: |cOXP_FRIENDLY_Gakin the Darkbinder|r takes it back." },
        { "goto", x = 39.22, y = 85.23, zone = "1453" },
        { "turnin", quest = 1688, text = "Turn in Surena Caledon" },
        { "target", name = "Gakin the Darkbinder" },
        { "goto", x = 39.22, y = 85.23, zone = "1453" },
        { "accept", quest = 1689, text = "Accept The Binding" },
        { "target", name = "Gakin the Darkbinder" },
        { "goto", x = 39.1, y = 84.4, zone = "1453" },
        { "item", item = 6928, text = "Use Bloodstone Choker (|cOXP_LOOT_Bloodstone Choker|r, on the circle in the crypt)" },
        { "goto", x = 25.1, y = 77.4, zone = "1453" },
        { "complete", obj = 1, quest = 1689, text = "Kill Summoned Voidwalker: 1" },
        { "mob", name = "Summoned Voidwalker" },
        { "goto", x = 39.22, y = 85.23, zone = "1453" },
        { "turnin", quest = 1689, text = "Turn in The Binding (|cOXP_FRIENDLY_Gakin the Darkbinder|r: Summon Voidwalker)" },
        { "target", name = "Gakin the Darkbinder" },
      },
      { only = "Shaman",
        { "text", text = "|cOXP_FRIENDLY_Bruegs Kindleborn|r" },
        { "text", text = "Back through the South Gate tunnel and up the trail to |cOXP_FRIENDLY_Bruegs Kindleborn|r' cave. Keep the |cOXP_LOOT_Fire Totem|r in your bags for good: every fire totem needs it." },
        { "goto", x = 87.94, y = 44.8, zone = "1426" },
        { "turnin", quest = 94468, text = "Turn in Call of Fire (|cOXP_FRIENDLY_Bruegs Kindleborn|r: Searing Totem, your |cOXP_LOOT_Fire Totem|r and the |cOXP_LOOT_Totem of Charged Flames|r)" },
        { "target", name = "Bruegs Kindleborn" },
        { "goto", only = "Shaman", x = 47.1, y = 13.79, zone = "1455" },
        { "train", only = "Shaman", text = "Train at |cOXP_FRIENDLY_Eldrun Stormbreaker|r" },
        { "target", name = "Eldrun Stormbreaker", only = "Shaman" },
      },
      { only = "NightElf Rogue",
        { "text", text = "Back to |cOXP_FRIENDLY_Syurna|r" },
        { "goto", x = 36.99, y = 21.91, zone = "1457" },
        { "turnin", quest = 2242, text = "Turn in Destiny Calls (|cOXP_FRIENDLY_Syurna|r, Darnassus)" },
        { "target", name = "Syurna" },
      },
      { only = "Priest", when = { { "onquest", quests = { 5675 } } },
        { "text", text = "Elune's Grace: Rohan's letter" },
        { "text", text = "Hand Rohan's letter to |cOXP_FRIENDLY_Priestess Alathea|r, on the upper balcony of the Temple of the Moon in Darnassus, beside |cOXP_FRIENDLY_Tyrande Whisperwind|r: the boat from Stormwind Harbor (or Menethil Harbor) to Auberdine, the boat on to Rut'theran Village, then the portal up into Darnassus." },
        { "goto", x = 39.52, y = 81.2, zone = "1457" },
        { "turnin", quest = 5675, text = "Turn in Elune's Grace (|cOXP_FRIENDLY_Priestess Alathea|r: Elune's Grace)" },
        { "target", name = "Priestess Alathea" },
      },
      { only = "Priest", when = { { "onquest", quests = { 5677 } } },
        { "text", text = "Feedback: Rohan's letter" },
        { "text", text = "Hand Rohan's letter to |cOXP_FRIENDLY_High Priestess Laurena|r at the altar of Stormwind's Cathedral of Light (the Deeprun Tram from |cOXP_PICK_Tinker Town|r in Ironforge): she teaches Feedback." },
        { "goto", x = 49.53, y = 44.6, zone = "1453" },
        { "turnin", quest = 5677, text = "Turn in Arcane Feedback (|cOXP_FRIENDLY_High Priestess Laurena|r: Feedback)" },
        { "target", name = "High Priestess Laurena" },
      },
      { only = "Priest", when = { { "onquest", quests = { 5678 } } },
        { "text", text = "Feedback: Alathea's letter" },
        { "text", text = "Hand Alathea's letter to |cOXP_FRIENDLY_High Priestess Laurena|r at the altar of Stormwind's Cathedral of Light (from Darnassus: the portal down to Rut'theran Village, the boat to Auberdine, then the boat to Stormwind Harbor): she teaches Feedback." },
        { "goto", x = 49.53, y = 44.6, zone = "1453" },
        { "turnin", quest = 5678, text = "Turn in Arcane Feedback (|cOXP_FRIENDLY_High Priestess Laurena|r: Feedback)" },
        { "target", name = "High Priestess Laurena" },
      },
      { only = "Priest", when = { { "onquest", quests = { 5647 } } },
        { "text", text = "Chastise: Alathea's letter" },
        { "text", text = "Hand Alathea's letter to |cOXP_FRIENDLY_High Priest Rohan|r in the |cOXP_PICK_Hall of Mysteries|r, Ironforge's |cOXP_PICK_Mystic Ward|r: from Darnassus, the boats via Rut'theran Village and Auberdine to Menethil Harbor, then the road north through the Wetlands and Loch Modan (or the boat to Stormwind Harbor and the Deeprun Tram)." },
        { "goto", x = 24.73, y = 8.16, zone = "1455" },
        { "turnin", quest = 5647, text = "Turn in Chastise (|cOXP_FRIENDLY_High Priest Rohan|r: Chastise)" },
        { "target", name = "High Priest Rohan" },
      },
      { only = "Priest", when = { { "onquest", quests = { 94820 } } },
        { "text", text = "Contingency Plan: a letter from another trainer" },
        { "text", text = "Any Contingency Plan letter goes to |cOXP_FRIENDLY_High Priestess Mims|r in the |cOXP_PICK_Hall of Mysteries|r, Ironforge's |cOXP_PICK_Mystic Ward|r." },
        { "goto", x = 24.59, y = 10, zone = "1455" },
        { "turnin", quest = 94820, text = "Turn in Contingency Plan (|cOXP_FRIENDLY_High Priestess Mims|r: Contingency Plan)" },
        { "target", name = "High Priestess Mims" },
      },
      { only = "Hunter", when = { { "turnedin", neg = true, quest = 6064 }, { "turnedin", neg = true, quest = 6063 } },
        { "text", text = "|cOXP_ENEMY_Gray Forest Wolf|r" },
        { "text", text = "Dismiss the boar first (right-click the pet portrait, Dismiss Pet): a released practice pet can turn on you. Gray Forest Wolves (level 7-8) run in the woods east of Goldshire, east of Crystal Lake." },
        { "goto", x = 58.44, y = 62.13, zone = "1429" },
        { "complete", obj = 1, quest = 94863, text = "Kill Gray Forest Wolf: 1 (Use the |cOXP_LOOT_Taming Rod|r on a living wolf)" },
