      { only = "Skyborne Hunter",
        { "text", text = "Class quest: {quest:6063} (Alliance)" },
        { "text", text = "|cOXP_FRIENDLY_Elayaa Easewind|r" },
        { "text", text = "At 10, |cOXP_FRIENDLY_Elayaa Easewind|r, a hunter trainer on Zephras Isle, may send you on to Valanaar with Taming the Beast. It is only a pointer: skip it if you are already in Valanaar." },
        { "xp", level = 10, text = "Reach level 10" },
        { "goto", x = 45.26, y = 44.24, zone = "2521" },
        { "accept", optional = true, quest = 94007, text = "Accept Taming the Beast" },
        { "target", name = "Elayaa Easewind" },
      },
      { only = "Skyborne Hunter",
        { "text", text = "|cOXP_FRIENDLY_Quel'ana Quickgale|r in Valanaar" },
        { "text", text = "|cOXP_FRIENDLY_Quel'ana Quickgale|r stands with the trainers by Valanaar's west gate, |cOXP_FRIENDLY_Quel'dora Quickgale|r beside her." },
        { "goto", x = 59.56, y = 72.63, zone = "2521" },
        { "turnin", optional = true, quest = 94007, text = "Turn in Taming the Beast" },
        { "target", name = "Quel'ana Quickgale" },
