        { "target", name = "Grif Wildheart" },
      },
      { only = "Dwarf Hunter", when = { { "onquest", neg = true, quests = { 94792, 94863, 94864, 94793 } }, { "turnedin", neg = true, quest = 94792 } },
        { "text", text = "|cOXP_ENEMY_Snow Leopard|r" },
        { "text", text = "Dismiss the boar first (right-click the pet portrait, Dismiss Pet): a released practice pet can turn on you. Snow Leopards (level 7-8) prowl the slopes south-east of Kharanos, more north-west and west of it; the smaller Juvenile Snow Leopards do not count." },
        { "goto", x = 48.29, y = 56.53, zone = "1426" },
        { "complete", obj = 1, quest = 6084, text = "Kill Snow Leopard: 1 (Use the |cOXP_LOOT_Taming Rod|r on a living leopard)" },
