        { "text", text = "Chastise: Laurena's letter" },
        { "text", text = "Hand Laurena's letter to |cOXP_FRIENDLY_High Priest Rohan|r in the |cOXP_PICK_Hall of Mysteries|r, Ironforge's |cOXP_PICK_Mystic Ward|r: he teaches Chastise." },
        { "goto", x = 24.73, y = 8.16, zone = "1455" },
        { "turnin", quest = 5645, text = "Turn in Chastise (|cOXP_FRIENDLY_High Priest Rohan|r: Chastise)" },
