      { only = "Human Rogue/Skyborne Rogue",
        { "text", text = "Class quest: {item:7907}" },
        { "text", text = "SI:7 (Goldshire)" },
        { "text", text = "At 16 |cOXP_FRIENDLY_Keryn Sylvius|r, the rogue trainer upstairs in the Lion's Pride Inn in Goldshire, sends you to |cOXP_FRIENDLY_Renzik \"The Shiv\"|r in Stormwind. Taking it shuts out the other towns' breadcrumbs." },
        { "xp", level = 16, text = "Reach level 16" },
