      { only = "Tauren Druid/Skyborne Druid",
        { "text", text = "To Thunder Bluff" },
        { "text", text = "|cOXP_FRIENDLY_Turak Runetotem|r on Elder Rise teaches you Cat Form." },
        { "goto", x = 76.48, y = 27.22, zone = "1456" },
