        { "target", name = "Mathiel" },
        { "goto", x = 59.51, y = 45.38, zone = "1457" },
        { "accept", quest = 1711, text = "Accept Mathiel's Armor" },
        { "target", name = "Mathiel" },
        { "goto", x = 59.51, y = 45.38, zone = "1457" },
        { "turnin", quest = 1711, text = "Turn in Mathiel's Armor" },
        { "target", name = "Mathiel" },
      },
      { only = "Dwarf Warrior/Gnome Warrior",
        { "text", text = "Klockmort Spannerspan" },
        { "text", text = "Ride the Deeprun Tram from Stormwind to Ironforge. Klockmort Spannerspan, a gnome smith, works in |cOXP_PICK_Tinker Town|r near the engineering trainers. He wants 20 |cOXP_LOOT_Searing Coral|r." },
        { "goto", x = 67.92, y = 46.1, zone = "1455" },
        { "turnin", quest = 1704, text = "Turn in Klockmort Spannerspan" },
        { "target", name = "Klockmort Spannerspan" },
        { "goto", x = 67.92, y = 46.1, zone = "1455" },
        { "accept", quest = 1708, text = "Accept Iron Coral" },
        { "target", name = "Klockmort Spannerspan" },
      },
      { only = "Dwarf Warrior/Gnome Warrior",
        { "text", text = "Iron Coral" },
        { "text", text = "The Iron Coral grows on the sea floor just south of Menethil Harbor, by the murloc huts and a wrecked boat: eight there and two south-east of the harbor, each back in 3 minutes, so you will wait for respawns to reach 20. The murlocs can net you underwater: watch your breath, and a |cOXP_LOOT_Draught of Water Breathing|r removes the risk." },
        { "goto", x = 9.31, y = 69.14, zone = "1437" },
        { "complete", obj = 1, quest = 1708, text = "Searing Coral: 20 (|cOXP_LOOT_Searing Coral|r, from Iron Coral)" },
      },
      { only = "Dwarf Warrior/Gnome Warrior",
        { "text", text = "Klockmort's Creation" },
        { "goto", x = 67.92, y = 46.1, zone = "1455" },
        { "turnin", quest = 1708, text = "Turn in Iron Coral" },
