        { "target", name = "Klockmort Spannerspan" },
        { "goto", x = 67.92, y = 46.1, zone = "1455" },
        { "turnin", quest = 1709, text = "Turn in Klockmort's Creation" },
        { "target", name = "Klockmort Spannerspan" },
      },
    },
  },
  {
    name = "21-23 Darkshore",
    group = "OpenXP Leveling (Alliance)",
    subgroup = "OpenXP 20-30",
    next = "22-25 Ashenvale, Wetlands & Stonetalon Mountains",
    only = "Alliance",
    source = "polestar:forever/alliance/03-darkshore-return",
    tags = { "forever" },
    steps = {
      {
        { "text", text = "Auberdine" },
        { "text", text = "From the dock, up to the north end of the village first (|cOXP_ENEMY_Thundris Windweaver|r, |cOXP_FRIENDLY_Alanndarian Nightsong|r by the moonwell, |cOXP_FRIENDLY_Archaeologist Hollee|r), then down the main street: the WANTED poster outside the inn, |cOXP_FRIENDLY_Terenthis|r at its east end, where the road leaves south. |cOXP_FRIENDLY_Sentinel Selarin|r stands beside |cOXP_FRIENDLY_Terenthis|r by the flight master; if she isn't there, she has been killed and respawns shortly: wait a moment." },
        { "goto", x = 37.4, y = 40.13, zone = "1439" },
