        { "goto", x = 53.48, y = 54.53, zone = "1437" },
        { "accept", quest = 98223, text = "Accept Old Habits (|cOXP_PICK_Tattered Spellbook|r: for |cOXP_FRIENDLY_Captain Stoutfist|r)" },
      },
      { when = { { "group", quest = 474 } },
        { "text", text = "Defeat Nek'rosh" },
        { "text", text = "These are elite mobs: grouping up is encouraged, look for people to do it with. |cOXP_ENEMY_Chieftain Nek'rosh|r is a level 32 elite: most classes solo it at level 34, but you may need help. Skip it if you are alone: the route has you grind the XP back.\nCareful: Shadowcasters stand on either side of him, and at least one is linked to him, so it joins when he is pulled. Non-elite centurions and captains are spread around his ring of tents." },
        { "goto", x = 53.5, y = 54.7, zone = "1437" },
        { "complete", obj = 1, quest = 474, text = "Nek'rosh's Head: 1" },
        { "mob", name = "Chieftain Nek'rosh" },
      },
      { when = { { "group", quest = 98310 } },
        { "text", text = "|cOXP_ENEMY_Golm|r" },
